#!/usr/bin/env bash
# READ ONLY: no sbatch, scancel, pkill, deletes or relabeling.
set -euo pipefail
STATE="${1:-${VERIFY_BASE:-/mnt/slurmfs-3090node3/user_data/zsong142/CAREPlanner/outputs/mainline_b/r1_offline_labels_v2}/latest_verify.env}"
MODE="${2:-main}"
[[ -f "$STATE" ]] || { echo "[ERROR] state not found: $STATE; use [state] from submit output" >&2;exit 2; }
# State must be the local file generated by submit.sh, not an untrusted download.
source "$STATE"
printf '[job] %s\n[out] %s\n[log] %s\n' "$JOB_ID" "$OUT" "$LOG"
case "$MODE" in
  main) echo '[read-only] Ctrl+C exits tail, not the job';tail --retry -n 160 -F "$LOG" ;;
  workers) for ((r=0;r<WORKERS;r++)); do echo "===== worker $r =====";f="$OUT/logs/worker_$r.log";if [[ -f "$f" ]];then tail -n 40 "$f";else echo '[not created yet]';fi;done ;;
  status) squeue -j "$JOB_ID" -o '%.18i %.24j %.10T %.10M %.10l %.20R' || true; sacct -X -j "$JOB_ID" --format=JobID,State,ExitCode,Elapsed || true ;;
  summary) for n in verification_summary.md verification_summary.json;do echo "===== $n =====";if [[ -f "$OUT/$n" ]];then cat "$OUT/$n";else echo '[not generated yet; see main/workers]';fi;done ;;
  *) echo 'usage: bash watch.sh [state.env] main|workers|status|summary' >&2;exit 2 ;;
esac
